CASES = {'trouble-0': {'boundary': 'Physical carrier before logical reachability', 'baseline': 'A server NIC and access port report carrier up at the intended speed; gateway traffic succeeds.', 'fault': 'After a patch-panel move, both ends report enabled but no carrier. The switch has no recent receive traffic.', 'test': 'Trace the labelled cable end to end; compare peer identity, media, supported optics and receive light or link indication. Substitute one known-good compatible patch lead on an owned test link.', 'diagnosis': 'The failed boundary is physical continuity or transceiver compatibility; enabled is administrative intent, not carrier evidence.', 'recovery': 'Both partners regain stable carrier at the expected speed; a bounded gateway and application test succeeds without new physical errors.', 'alternative': 'A disabled peer or err-disabled switch port also prevents useful service. Confirm administrative and protection state before blaming the cable.', 'guard': 'Do not look into fiber or disconnect an unidentified production circuit. Record labels and preserve the original patch map.', 'scope': 'Authored tabletop evidence; browser selection does not execute a device change, reproduce timing or prove a physical repair.'}, 'trouble-1': {'boundary': 'Counter deltas and direction', 'baseline': 'At 12:00 an interface records 100 input errors and 20 output drops; at 12:01 those values remain unchanged.', 'fault': 'During a slow transfer, output drops rise from 20 to 420 in 60 seconds while input CRC stays at zero.', 'test': 'Take timestamped samples from the same interface and epoch; compare output queue drops with utilization and offered bursts. Preserve both endpoint observations.', 'diagnosis': 'There are 400 new output drops, about 6.67 per second. This supports an egress queue/capacity investigation, not proof of corrupt received frames.', 'recovery': 'After the scoped queue or load correction, comparable traffic meets latency/loss objectives and the output-drop rate returns to its agreed baseline.', 'alternative': 'A counter reset or interface replacement invalidates subtraction. A low minute average can conceal microbursts.', 'guard': 'Do not clear counters before collecting the incident interval. Increasing buffers can trade packet loss for latency and is not a universal repair.', 'scope': 'Authored tabletop evidence; browser selection does not execute a device change, reproduce timing or prove a physical repair.'}, 'trouble-2': {'boundary': 'Corrupt reception versus congestion', 'baseline': 'A receiving port has a stable FCS/CRC count of 7 across two samples under ordinary load.', 'fault': 'The receiver rises from 7 to 67 CRC errors in 30 seconds. A separate output-drop counter is unchanged.', 'test': 'Localize the receiving interface and upstream segment, compare the peer and adjacent-hop counters, then change one compatible cable/optic component in a controlled window.', 'diagnosis': 'The receiver observed 60 additional corrupt frames, or 2 per second. The count localizes observed corruption but does not alone identify the faulty component.', 'recovery': 'Repeat the same traffic interval after repair: no new CRC errors at the identified receiver and the original application succeeds.', 'alternative': 'Duplex problems on legacy copper and forwarding of corrupted frames on some switch architectures can complicate localization; inspect the actual platform.', 'guard': 'Save original samples and optic identity. Do not equate a lifetime nonzero counter with a continuing fault.', 'scope': 'Authored tabletop evidence; browser selection does not execute a device change, reproduce timing or prove a physical repair.'}, 'trouble-3': {'boundary': 'Legacy Ethernet negotiation agreement', 'baseline': 'An owned 100 Mb/s copper test link has both partners negotiating full duplex with stable counters.', 'fault': 'One partner is forced to 100/full; the other reports 100/half. Throughput collapses under bidirectional traffic and late collisions appear on the half-duplex side.', 'test': 'Read configured and operational speed/duplex on both ends. Correlate the mismatch with load-sensitive collision and error deltas.', 'diagnosis': 'The partners disagree on medium access behavior. Carrier and equal speed do not establish duplex agreement.', 'recovery': 'Restore a mutually supported negotiation policy on both partners; verify matching full duplex, stable counters and bidirectional application transfer.', 'alternative': 'Bad cabling may also cause receive errors, but cannot explain away explicit contradictory duplex observations.', 'guard': 'This fixture is legacy 10/100 copper. Do not generalize half-duplex forcing to modern fiber or all gigabit platforms.', 'scope': 'Authored tabletop evidence; browser selection does not execute a device change, reproduce timing or prove a physical repair.'}, 'trouble-4': {'boundary': 'VLAN membership across every hop', 'baseline': 'Client port is access VLAN 20; both trunk endpoints carry VLAN 20; the gateway SVI is reachable.', 'fault': 'Client carrier remains up, but VLAN 20 is missing from the uplink allowed list. VLAN 10 users on the same uplink work.', 'test': 'Follow VLAN 20 from ingress classification through operational trunk membership and STP forwarding to the gateway; compare both trunk ends.', 'diagnosis': 'The failure is selective VLAN admission on the uplink, not proof of a dead physical link or failed entire switch.', 'recovery': 'Restore only the intended VLAN membership; verify VLAN 20 gateway/application access and continued isolation from unauthorized VLANs.', 'alternative': 'Wrong access VLAN or non-forwarding STP state produces a similar endpoint symptom; test these boundaries before altering the trunk.', 'guard': 'Do not replace the allowed list with all VLANs. Capture exact existing membership for rollback.', 'scope': 'Authored tabletop evidence; browser selection does not execute a device change, reproduce timing or prove a physical repair.'}, 'trouble-5': {'boundary': 'Intentional blocking versus topology instability', 'baseline': 'A redundant triangle has one expected root and a stable alternate blocked path for VLAN 20.', 'fault': 'After an unmanaged bridge is attached on two unprotected access ports, MAC addresses move repeatedly and broadcast volume rises. The expected forwarding tree no longer explains the observed physical paths.', 'test': 'Record root identity, per-VLAN roles, topology-change timestamps and MAC moves; correlate the new physical connection and guard logs.', 'diagnosis': 'The attachment introduced an unexpected bridging path. A blocked alternate port itself is normal protection, not the cause to remove.', 'recovery': 'Remove or correct the unauthorized lab bridge; confirm expected root/roles, stable MAC learning, traffic recovery and retained edge protection.', 'alternative': 'A flapping legitimate link can also cause topology changes. A change counter alone does not prove a loop.', 'guard': 'Never disable STP or clear a guard condition without resolving its trigger. Preserve an independent management path.', 'scope': 'Authored tabletop evidence; browser selection does not execute a device change, reproduce timing or prove a physical repair.'}, 'trouble-6': {'boundary': 'Configured members versus operational bundle', 'baseline': 'Two intended links are bundled in one LACP port-channel with matching trunk policy and a common peer.', 'fault': 'One member is suspended after its VLAN settings diverge; the logical channel stays up with one member.', 'test': 'Compare operational aggregation state, peer/system identity and member compatibility. Test multiple traffic flows and remaining capacity separately.', 'diagnosis': 'The logical link masks a loss of redundancy and capacity. A configured channel-group is not proof of member participation.', 'recovery': 'Restore compatible settings using the supported platform procedure; confirm both members bundle, allowed traffic works and a controlled single-link failure meets the objective.', 'alternative': 'One flow remaining on one member is normal hashing behavior and does not itself indicate a failed bundle.', 'guard': 'Do not force a static channel to hide LACP mismatch. Preserve the working member and stop if peer identities differ.', 'scope': 'Authored tabletop evidence; browser selection does not execute a device change, reproduce timing or prove a physical repair.'}, 'trouble-7': {'boundary': 'Forward and return lookup in the correct table', 'baseline': 'Client 192.0.2.10 reaches service 198.51.100.20 through a router; both directions have valid routes.', 'fault': 'A request reaches the service, but the service-side router has no route back to 192.0.2.0/24 in the relevant VRF.', 'test': 'Check destination lookup and recursive next-hop resolution in both directions using the actual source and VRF. Compare endpoint capture with router forwarding evidence.', 'diagnosis': 'The observed request path is intact; the missing return route prevents the response from completing the transaction.', 'recovery': 'Restore the intended return prefix in the correct table and verify a fresh application exchange from the original client without cross-VRF leakage.', 'alternative': 'A host firewall could suppress replies even with a valid return route. Establish whether a reply is generated before assigning all blame to routing.', 'guard': 'Do not add a broad default route to conceal a missing specific path. Record ownership and the exact route to remove on rollback.', 'scope': 'Authored tabletop evidence; browser selection does not execute a device change, reproduce timing or prove a physical repair.'}, 'trouble-8': {'boundary': 'Neighbor, database, RIB and data plane', 'baseline': 'Two point-to-point lab routers have matching OSPF area/timers and a Full adjacency with a learned remote prefix.', 'fault': 'After a timer change, captured Hellos advertise different intervals and the adjacency disappears.', 'test': 'Compare received Hello fields and interface settings at both peers within the same process/area. Separate neighbor formation from prefix origination and route installation.', 'diagnosis': 'The mismatched Hello timing is an adjacency acceptance fault in this supplied case, not evidence of BGP policy failure.', 'recovery': 'Restore the captured compatible timer values; verify Full, the expected LSA, installed prefix/next hop and an endpoint exchange.', 'alternative': 'No received Hello could instead mean filtering, carrier, addressing or passive configuration; an absent neighbor alone does not select one cause.', 'guard': 'Do not restart every routing process or disable authentication as a diagnostic shortcut. Save original interface settings.', 'scope': 'Authored tabletop evidence; browser selection does not execute a device change, reproduce timing or prove a physical repair.'}, 'trouble-9': {'boundary': 'Session health versus route policy', 'baseline': 'Two lab BGP speakers are Established; an approved documentation prefix is advertised, accepted and installed.', 'fault': 'The session remains Established after an inbound policy change, but the approved prefix is absent from the accepted routes.', 'test': 'Compare advertised, received where supported, accepted and best-path/installed views for the exact prefix and address family; inspect the effective policy and next hop.', 'diagnosis': 'The supplied evidence points to route admission policy, not a TCP session failure. Established describes the session rather than acceptance of every prefix.', 'recovery': 'Repair the narrow policy clause; verify approved prefix admission and installation, rejection of an unauthorized prefix and endpoint reachability.', 'alternative': 'A missing origin advertisement or unresolved next hop can also remove an installed route. Determine the first view where the prefix disappears.', 'guard': 'Never permit every prefix to test policy. Use supported soft refresh only when required; avoid disruptive hard resets.', 'scope': 'Authored tabletop evidence; browser selection does not execute a device change, reproduce timing or prove a physical repair.'}, 'trouble-10': {'boundary': 'DHCP exchange across the relay', 'baseline': 'A VLAN 20 client receives a lease from the intended subnet through a relay to the server.', 'fault': 'DISCOVER reaches the relay but no forwarded request appears at the server after the helper destination changes.', 'test': 'Correlate transaction identity across client, relay and server observations; verify relay destination, routing and filters before changing the scope.', 'diagnosis': 'The first demonstrated failed handoff is relay-to-server delivery. Pool exhaustion is not supported until the request reaches the server.', 'recovery': 'Restore the intended relay target; verify DORA, subnet/mask/gateway/DNS options and a fresh client service test; confirm other scopes remain isolated.', 'alternative': 'A server receiving DISCOVER without offering a lease warrants scope/availability checks; an OFFER failing to return shifts the investigation to the return path.', 'guard': 'Use a disposable client for renew/release testing. Do not interrupt active production leases or introduce an unauthorized DHCP server.', 'scope': 'Authored tabletop evidence; browser selection does not execute a device change, reproduce timing or prove a physical repair.'}, 'trouble-11': {'boundary': 'Resolver answer, authority and negative cache', 'baseline': 'The intended resolver returns the current A record for app.example.test and the application uses it successfully.', 'fault': 'The authoritative test zone has the new record, but one recursive resolver continues returning a cached NXDOMAIN before its negative TTL expires.', 'test': 'Compare the exact name, type and resolver with an authoritative query and the cached answer/TTL. Distinguish NXDOMAIN, NOERROR with no requested data, SERVFAIL and timeout.', 'diagnosis': 'The supplied mismatch is negative-cache state at one resolver; an authoritative record does not instantly invalidate every cache.', 'recovery': 'After the scoped expiry or authorized cache action, the intended resolver returns the correct answer and a new application request reaches the intended endpoint.', 'alternative': 'A different search suffix, split DNS view or queried record type can make two apparently similar queries non-equivalent.', 'guard': 'Do not flush every resolver or point clients at public DNS to bypass an internal view. Retain query details without sensitive names.', 'scope': 'Authored tabletop evidence; browser selection does not execute a device change, reproduce timing or prove a physical repair.'}, 'trouble-12': {'boundary': 'Translation tuples and reverse state', 'baseline': 'Inside client 192.0.2.10:53000 maps to documentation address 203.0.113.5:40001 for an approved service.', 'fault': 'The request is observed after translation, but the response returns through a different unsynchronized stateful gateway.', 'test': 'Correlate original and translated five-tuples at ingress/egress and the returning gateway; check mapping lifetime, routing and filtering separately.', 'diagnosis': 'The reply misses the device holding the mapping. A successful outbound translation does not prove reverse delivery.', 'recovery': 'Restore the intended symmetric/state-compatible path; verify a new connection and its reverse translation, while unsolicited traffic remains denied.', 'alternative': 'Port exhaustion or a rule that never matches would instead prevent the outbound mapping; neither is proved by this successful translated request.', 'guard': 'Do not clear all NAT state or expose inside addresses to diagnose one flow. Keep the test tuple bounded and document translation order for the platform.', 'scope': 'Authored tabletop evidence; browser selection does not execute a device change, reproduce timing or prove a physical repair.'}, 'trouble-13': {'boundary': 'Ordered ACL matching at an applied boundary', 'baseline': 'Policy permits a test client to TCP 443 on a service and denies unrelated access.', 'fault': 'A broader deny appears before the intended permit. The deny counter increases on each fresh test connection.', 'test': 'Read effective rule order, attachment interface/direction, address family and pre/post-NAT tuple context; correlate a bounded test with counter deltas.', 'diagnosis': 'First matching rule order shadows the later permit for this test. Merely finding a permit in the text is insufficient.', 'recovery': 'Apply the reviewed narrow ordering correction and verify both the permitted transaction and a deliberately denied control flow.', 'alternative': 'A correct ACL on the wrong interface or direction will not explain a matching counter there; confirm the real traffic path.', 'guard': 'Keep management access and a rollback path. Do not append an any-any permit as a connectivity experiment.', 'scope': 'Authored tabletop evidence; browser selection does not execute a device change, reproduce timing or prove a physical repair.'}, 'trouble-14': {'boundary': 'Stateful session lifecycle', 'baseline': 'A new TCP connection traverses the intended firewall zones and receives an allowed response.', 'fault': 'After a routing change, SYN enters firewall A while SYN-ACK reaches firewall B without synchronized session state.', 'test': 'Correlate both directions of a new five-tuple with route, zone, rule and session/drop reason evidence. Distinguish existing sessions from new-session policy.', 'diagnosis': 'Asymmetric traversal lacks the required state on B in this case; a permissive-looking static rule alone cannot establish session acceptance.', 'recovery': 'Restore a supported state-compatible traffic path; verify a new handshake and application transaction, denied control traffic and the agreed HA behavior.', 'alternative': 'TLS negotiation or an unhealthy listener can fail after a successful handshake. A firewall allow log is not proof of application health.', 'guard': 'Do not disable inspection or expose all zones. Sanitize captures and change only the demonstrated path or rule.', 'scope': 'Authored tabletop evidence; browser selection does not execute a device change, reproduce timing or prove a physical repair.'}, 'trouble-15': {'boundary': 'Association, authentication, addressing and service', 'baseline': 'A test client associates with the intended AP, authenticates, receives an address and opens the service.', 'fault': 'The client is associated and authenticated but remains without a lease. Controller evidence places it at the DHCP stage.', 'test': 'Inspect client state and correlate DHCP requests across the WLAN/VLAN mapping and relay. Compare RF retries separately from addressing evidence.', 'diagnosis': 'The supplied evidence has passed association/authentication but not addressing. Strong signal alone does not establish network service.', 'recovery': 'Correct the intended WLAN-to-VLAN or relay handoff; confirm authentication remains required, a correct lease arrives and a fresh application request works.', 'alternative': 'High retry rates or roaming problems require RF/channel evidence; they cannot be inferred solely from an absent address.', 'guard': 'Use an owned test SSID/client. Never turn off encryption or authentication to make the status look healthy.', 'scope': 'Authored tabletop evidence; browser selection does not execute a device change, reproduce timing or prove a physical repair.'}, 'trouble-16': {'boundary': 'Hardware evidence versus guest symptom', 'baseline': 'A rack server has redundant power feeds, normal thermal readings and a stable hardware event log.', 'fault': 'Guests remain running but the management controller records loss of PSU B input at the same time as a rack power alert.', 'test': 'Compare PSU identity, input state and PDU/feed map with timestamped events. Distinguish lost input from an internal PSU failure before replacing parts.', 'diagnosis': 'The server has lost power redundancy despite continued service. The shared feed observation makes upstream power a candidate requiring inspection.', 'recovery': 'An authorized operator restores the intended independent input; both supplies report healthy and the original workload remains stable through the observation window.', 'alternative': 'An old unacknowledged alarm may not be active; correlate current sensor state and incident time rather than only alarm color.', 'guard': 'Electrical work is for qualified personnel. Do not pull the surviving feed or power-cycle a running host as a first test.', 'scope': 'Authored tabletop evidence; browser selection does not execute a device change, reproduce timing or prove a physical repair.'}, 'trouble-17': {'boundary': 'Array state, member identity and recoverability', 'baseline': 'A documented four-member RAID 5 virtual disk is optimal with a verified independent backup.', 'fault': 'The virtual disk is degraded after one member is reported failed; applications still read data.', 'test': 'Capture controller/virtual-disk/member identifiers, error logs, rebuild state and backup status. Match enclosure/slot and serial number before proposing replacement.', 'diagnosis': 'The array is serving data with reduced redundancy. Continued reads do not establish safety from a second failure or unreadable sector.', 'recovery': 'Use the exact supported controller recovery procedure in an authorized lab; verify the correct member, completed rebuild/consistency status and application data against a known reference.', 'alternative': 'A cable/backplane/controller fault can make several members disappear together. Do not assume simultaneous disk media failures.', 'guard': 'Do not initialize, force online, clear foreign metadata or replace guessed disks. Stop when member identity or recoverable state is uncertain.', 'scope': 'Authored tabletop evidence; browser selection does not execute a device change, reproduce timing or prove a physical repair.'}, 'trouble-18': {'boundary': 'Initiator to target through independent fabrics', 'baseline': 'A host has the intended LUN through two independent FC fabrics and supported multipath behavior.', 'fault': 'After a zoning edit, fabric A remains operational but the expected target login/path on fabric B disappears.', 'test': 'Trace HBA/WWPN login, effective zone membership, target port, LUN masking and host multipath inventory in order. Compare the two fabrics without assuming they are identical.', 'diagnosis': 'The first observed loss follows the changed fabric-B admission boundary. One surviving path explains service continuity while redundancy is impaired.', 'recovery': 'Restore the intended narrowly scoped zone membership; verify target visibility, correct LUN identity, multipath state and controlled failover under the supported policy.', 'alternative': 'Correct zoning without LUN masking still leaves the host without the intended device; each boundary needs its own evidence.', 'guard': 'Do not merge fabrics, zone every initiator to every target or rescan blindly during uncertain storage state. Preserve WWPN and LUN identity.', 'scope': 'Authored tabletop evidence; browser selection does not execute a device change, reproduce timing or prove a physical repair.'}, 'trouble-19': {'boundary': 'Guest, VMkernel, management and storage scope', 'baseline': 'An ESXi host is manageable and a VM can perform an application read from its datastore.', 'fault': 'Management remains reachable while VM I/O stalls; host evidence shows all paths to that datastore unavailable.', 'test': 'Correlate VM symptoms with host storage/path events, datastore identity and fabric/array observations. Distinguish management health from guest I/O and APD from an explicit permanent-loss report.', 'diagnosis': 'The affected dependency is datastore access despite a functioning management plane. The fixture reports all-path unavailability, not proof of permanent data loss.', 'recovery': 'Restore the supported storage path, verify host/datastore accessibility and a fresh application I/O operation; reconcile HA/restart effects and consistency before closure.', 'alternative': 'CPU ready time or guest service faults can also cause apparent slowness. Check whether symptoms correlate specifically with the affected datastore.', 'guard': 'Do not mass-reboot hosts, detach active devices or delete/recreate a datastore. Capture support evidence and follow release-specific recovery guidance.', 'scope': 'Authored tabletop evidence; browser selection does not execute a device change, reproduce timing or prove a physical repair.'}, 'trouble-20': {'boundary': 'Timeline, common dependencies and recovery order', 'baseline': 'Two application racks have separate compute capacity and an agreed client availability objective.', 'fault': 'At 09:00 a shared DNS service fails; both racks lose name-based application access while direct addressed test endpoints remain reachable.', 'test': 'Build a timestamped impact/dependency map with clock uncertainty; compare DNS queries, direct endpoint tests and recent changes. Assign incident coordination and a separate recovery owner.', 'diagnosis': 'The evidence favors a shared name-resolution dependency over simultaneous independent compute failures. Correlation narrows the hypothesis but still requires a confirming test.', 'recovery': 'Recover the scoped DNS dependency, verify name-based transactions from both racks and denied controls, then observe sustained service before closing and record follow-up owners.', 'alternative': 'A direct-IP probe may bypass TLS host naming or a load balancer; use it only to isolate a boundary, not to claim application recovery.', 'guard': 'Preserve the incident timeline and independent communication channel. Prefer reversible mitigation; never perform competing uncoordinated changes.', 'scope': 'Authored tabletop evidence; browser selection does not execute a device change, reproduce timing or prove a physical repair.'}}
# END AUTHORED CASES

def digest(p):
    return hashlib.sha256(p.read_bytes()).hexdigest()

def run(interrupt=False):
    result = {'scope': 'ACTUAL LOCAL FILE OPERATIONS; not a device or network test'}
    with tempfile.TemporaryDirectory(prefix='infra-troubleshooting-') as folder:
        target = Path(folder) / 'service.json'
        original = b'{"service":"example.test","port":443}\n'
        target.write_bytes(original)
        baseline = digest(target)
        result['baseline'] = json.loads(target.read_text())
        try:
            target.write_text('{"service":"example.test","port":444}\n', encoding='utf-8')
            observed = json.loads(target.read_text())
            result['fault'] = observed
            result['detected'] = observed['port'] != result['baseline']['port'] and digest(target) != baseline
            if interrupt:
                raise InterruptedError('Intentional interruption after detection')
        except InterruptedError as e:
            result['interruption'] = str(e)
        finally:
            target.write_bytes(original)
            result['restored'] = digest(target) == baseline and json.loads(target.read_text()) == result['baseline']
    result['cleaned'] = not Path(folder).exists()
    result['result'] = 'PASS' if result['detected'] and result['restored'] and result['cleaned'] else 'FAIL'
    return result

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument('--topic', choices=['trouble-'+str(i) for i in range(21)])
    mode.add_argument('--run', action='store_true')
    parser.add_argument('--interrupt', action='store_true', help='Rehearse interruption and verify restoration; requires --run')
    args = parser.parse_args()
    if args.interrupt and not args.run:
        parser.error('--interrupt requires --run')
    if args.topic:
        result = {**CASES[args.topic], 'scope':'AUTHORED', 'topic':args.topic}
    else:
        result = run(args.interrupt)
    print(json.dumps(result, indent=2))
    return 0 if result.get('result', 'PASS') == 'PASS' else 1

if __name__ == '__main__':
    raise SystemExit(main())
